        for n in to_fail:
            if H.has_node(n):
                H.remove_node(n)

        rounds += 1

    # Size of the largest connected component after cascade finishes
    if H.number_of_nodes() == 0:
        final_size = 0
    else:
        final_size = len(max(nx.connected_components(H), key=len))

